import sys

def main():
    lines = []
    for line in sys.stdin:
        lines.append(line.rstrip('\n'))

    if not lines:
        return

    op = lines[0].strip().lower()

    contacts = {}

    if op == 'insert':
        if len(lines) >= 2:
            parts1 = lines[1].strip().split()
            cust_id = int(parts1[0])
            name = ' '.join(parts1[1:]) if len(parts1) > 1 else ''
            email = lines[2].strip() if len(lines) > 2 else ''
            phone = lines[3].strip() if len(lines) > 3 else ''

            if cust_id in contacts:
                print('Contact with this ID already exists.')
            else:
                contacts[cust_id] = {'name': name, 'email': email, 'phone': phone}
                print('Contact inserted successfully.')

    elif op == 'update':
        if len(lines) >= 2:
            cust_id = int(lines[1].strip())
            if cust_id in contacts:
                email = lines[2].strip() if len(lines) > 2 else contacts[cust_id]['email']
                phone = lines[3].strip() if len(lines) > 3 else contacts[cust_id]['phone']
                contacts[cust_id]['email'] = email
                contacts[cust_id]['phone'] = phone
                print('Contact updated successfully.')
            else:
                print('Contact not found.')

    elif op == 'delete':
        if len(lines) >= 2:
            cust_id = int(lines[1].strip())
            if cust_id in contacts:
                del contacts[cust_id]
                print('Contact deleted successfully.')
            else:
                print('Contact not found.')

    elif op == 'display':
        if not contacts:
            print('No contacts found.')
        else:
            for cid in sorted(contacts.keys()):
                c = contacts[cid]
                print(f"{cid} {c['name']} {c['email']} {c['phone']}")

    else:
        if op == 'exit':
            pass
        else:
            print('Invalid operation.')

if __name__ == '__main__':
    main()
